import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"What is ApptiveGrid","description":"The core concepts of ApptiveGrid — Space, Grid, Entry, Field, View, Form, Page, and Flow.","frontmatter":{"title":"What is ApptiveGrid","description":"The core concepts of ApptiveGrid — Space, Grid, Entry, Field, View, Form, Page, and Flow."},"headers":[],"relativePath":"en/erste-schritte/was-ist-apptivegrid.md","filePath":"en/erste-schritte/was-ist-apptivegrid.md","lastUpdated":1787319236000}'),i={name:"en/erste-schritte/was-ist-apptivegrid.md"};function r(o,e,l,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="what-is-apptivegrid" tabindex="-1">What is ApptiveGrid <a class="header-anchor" href="#what-is-apptivegrid" aria-label="Permalink to &quot;What is ApptiveGrid&quot;">​</a></h1><p>ApptiveGrid is a platform that lets you work without writing code. You manage structured data, capture it through forms, automate workflows, and deliver the result as a portal or embedded application.</p><p>This page explains the terms that recur throughout the documentation and the interface. If you&#39;re new, read it first — every other page assumes you know these terms.</p><h2 id="the-basic-model-in-four-steps" tabindex="-1">The basic model in four steps <a class="header-anchor" href="#the-basic-model-in-four-steps" aria-label="Permalink to &quot;The basic model in four steps&quot;">​</a></h2><p>ApptiveGrid follows one continuous flow:</p><ol><li><strong>Data</strong> lives in a <strong>Grid</strong> — a table.</li><li><strong>Capture</strong> happens through <strong>Forms</strong>, which write to a Grid.</li><li><strong>Automation</strong> is handled by <strong>Flows</strong>, which react to events.</li><li><strong>Delivery</strong> happens through <strong>Pages</strong>, which you publish as a <strong>Portal</strong>.</li></ol><p>All of this lives inside a <strong>Space</strong>.</p><h2 id="the-terms-in-detail" tabindex="-1">The terms in detail <a class="header-anchor" href="#the-terms-in-detail" aria-label="Permalink to &quot;The terms in detail&quot;">​</a></h2><h3 id="space" tabindex="-1">Space <a class="header-anchor" href="#space" aria-label="Permalink to &quot;Space&quot;">​</a></h3><p>A Space is the top-level organizational unit. It contains Grids, Pages, and Flows.</p><p>The Space is also the unit that access rights, plan, and seats are tied to. When you invite someone, you invite them into a Space — not into a single Grid. When you subscribe to a plan, you subscribe for a Space.</p><p>Typical breakdown: one Space per team, per project, or per client.</p><h3 id="grid" tabindex="-1">Grid <a class="header-anchor" href="#grid" aria-label="Permalink to &quot;Grid&quot;">​</a></h3><p>A Grid is a table of structured data. It&#39;s what you know from a spreadsheet — except that every column has a fixed type.</p><p>A Space can contain any number of Grids, and Grids can be linked to one another.</p><h3 id="entry" tabindex="-1">Entry <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Entry&quot;">​</a></h3><p>An Entry is a row in a Grid. In the German interface it&#39;s called <em>Eintrag</em>.</p><div class="tip custom-block"><p class="custom-block-title">Terms that mean the same thing</p><p>In a few places in the interface, <em>Entity</em> or <em>Record</em> shows up instead of &quot;Entry&quot; — for example in the field type <em>Link record</em>. It always means the same thing: a row in a Grid.</p></div><h3 id="field" tabindex="-1">Field <a class="header-anchor" href="#field" aria-label="Permalink to &quot;Field&quot;">​</a></h3><p>A Field is a column of a Grid. Every Field has a <strong>Column type</strong>, which determines which values are allowed and how they&#39;re displayed, filtered, and sorted.</p><p>There are column types for text, numbers, dates, select lists, files, addresses, signatures, links to other Grids, and calculated values. You&#39;ll find the full list in the <a href="/en/referenz/spaltentypen">Column types reference</a>.</p><p><strong>Column</strong> means the same thing as Field. The interface uses both.</p><h3 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h3><p>A View is a specific representation of a Grid. It determines:</p><ul><li>which Entries are visible (filter),</li><li>what order they appear in (sorting),</li><li>how they&#39;re bundled (grouping),</li><li>which columns are visible and in what order.</li></ul><p>Crucially: <strong>a View doesn&#39;t change the data.</strong> It&#39;s a lens on the same Grid. Multiple Views on one Grid show the same Entries in different ways.</p><p>There are seven View types: Grid View (table), Kanban, Calendar, Map, Gallery, List, and Timeline. Details under <a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a>.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t confuse Grid and View</p><p>This is the most common point of confusion in ApptiveGrid.</p><ul><li>The <strong>Grid</strong> holds the data. Delete it, and the data is gone.</li><li>A <strong>View</strong> holds only display rules. Delete it, and the data remains.</li></ul><p>But be careful: forms and shared links are attached to a View. Delete a View, and the forms built from it stop working. The interface warns you when deleting, noting that any forms you&#39;ve created will no longer work afterward.</p></div><h3 id="form" tabindex="-1">Form <a class="header-anchor" href="#form" aria-label="Permalink to &quot;Form&quot;">​</a></h3><p>A Form is an input mask for a Grid. You choose which fields to ask for, design its appearance, and share the Form as a link, QR code, or embedded on your website.</p><p>Forms can create new Entries or edit existing ones.</p><p>People who fill out a Form need <strong>no ApptiveGrid account</strong> — unless you&#39;ve explicitly restricted access.</p><h3 id="page-and-block" tabindex="-1">Page and Block <a class="header-anchor" href="#page-and-block" aria-label="Permalink to &quot;Page and Block&quot;">​</a></h3><p>A <strong>Page</strong> is a freely composed interface. You build it from <strong>Blocks</strong>: headings, text paragraphs, images, input fields, embedded views, reports, layout containers.</p><p>Publish a Page, and you get a <strong>Portal</strong> — a standalone web page you can share or embed in your website.</p><div class="tip custom-block"><p class="custom-block-title">&quot;Page&quot; has three meanings</p><p>Watch for this as you read the interface:</p><ol><li><strong>Page (Portal)</strong> — an interface built from Blocks. This is what the chapter <a href="/en/seiten/was-sind-seiten">Pages and Portals</a> covers.</li><li><strong>Form page</strong> — a section within a multi-page Form.</li><li><strong>Flow page</strong> — a page that a Flow shows to a person for input.</li></ol><p>This documentation always names them explicitly.</p></div><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3><p>A Flow is an automated workflow. It&#39;s made up of <strong>Steps</strong> that run one after another.</p><p>Every Flow starts with exactly one <strong>Trigger</strong> — the triggering event. For example: a new Entry was created, a Form was submitted, or an external system made a call.</p><p><strong>Actions</strong> follow: send an email, update an Entry, generate a file, call another system. <strong>Helper steps</strong> such as <em>Router</em>, <em>Parallel</em>, and <em>Wait</em> control the flow.</p><p>A single execution of a Flow is called a <strong>Run</strong> (labeled <em>Previous runs</em> in the interface).</p><h3 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h3><p>A Link is an externally shareable address. ApptiveGrid generates Links for Forms, Views, Pages (Portals), Flow starts, and invitations.</p><p>All Links of a Space are visible in one place — see <a href="/en/zusammenarbeit/externe-links">External links at a glance</a>. This is the most important page when you want to check what&#39;s reachable from outside.</p><h2 id="how-the-pieces-fit-together" tabindex="-1">How the pieces fit together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the pieces fit together&quot;">​</a></h2><p>A typical setup looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Space &quot;Events&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid &quot;Registrations&quot;</span></span>
<span class="line"><span>│   ├── View &quot;All registrations&quot;       (Table)</span></span>
<span class="line"><span>│   ├── View &quot;Open&quot;                    (Table, filtered)</span></span>
<span class="line"><span>│   ├── View &quot;By date&quot;                 (Calendar)</span></span>
<span class="line"><span>│   └── Form &quot;Registration&quot;            → writes new entries</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Grid &quot;Events&quot;</span></span>
<span class="line"><span>│   └── linked with &quot;Registrations&quot;</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Flow &quot;Send confirmation&quot;</span></span>
<span class="line"><span>│   ├── Trigger: New entry via form</span></span>
<span class="line"><span>│   └── Action:  Email to the registering person</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Page &quot;Attendee portal&quot;             → published as a portal</span></span>
<span class="line"><span>    └── Block: embedded &quot;Open&quot; view</span></span></code></pre></div><p>The registration comes in through the Form, lands as an Entry in the Grid, triggers the Flow, and shows up in the Portal. All within the same Space.</p><h2 id="what-to-do-next" tabindex="-1">What to do next <a class="header-anchor" href="#what-to-do-next" aria-label="Permalink to &quot;What to do next&quot;">​</a></h2><ul><li><a href="/en/erste-schritte/oberflaeche">The interface at a glance</a> — where to find what</li><li><a href="/en/erste-schritte/schnellstart">Your first app in 15 minutes</a> — a full walkthrough example</li><li><a href="/en/grids/grid-anlegen">Your first Grid</a> — if you&#39;d rather dive straight into data</li></ul><p>All the terms again in one place: <a href="/en/referenz/glossar">Glossary</a>.</p>`,51)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
